class Solution:

	def satisfyEqn(self, a, n):
		d = dict()
		s = list()
		sum = 0
		for i in range(n):
			for j in range(i + 1, n):
				sum = a[i] + a[j]
				if sum not in d:
					d[sum] = [i, j]
				elif i != d[sum][0] and j != d[sum][0] and (i != d[sum][1]) and (j != d[sum][1]):
					s.append([d[sum][0], d[sum][1], i, j])
		if len(s) == 0:
			return [-1, -1, -1, -1]
		return min(s)
